insert into public.brands (id, name, website, sort) values ('nespresso', 'Nespresso', 'https://www.nespresso.com/fr/fr/order/capsules/original', 1)
  on conflict (id) do update set name = excluded.name, website = excluded.website, sort = excluded.sort;
insert into public.brands (id, name, website, sort) values ('lor', 'L''Or Espresso', 'https://www.lorespresso.com/fr_fr/capsules-de-cafe/single-capsules', 2)
  on conflict (id) do update set name = excluded.name, website = excluded.website, sort = excluded.sort;
insert into public.brands (id, name, website, sort) values ('starbucks', 'Starbucks', 'https://www.starbucksathome.com/fr/produits/starbucks-nespresso', 3)
  on conflict (id) do update set name = excluded.name, website = excluded.website, sort = excluded.sort;
insert into public.brands (id, name, website, sort) values ('carte-noire', 'Carte Noire', 'https://www.cartenoire.fr/fr/cafes/capsules/nespresso', 4)
  on conflict (id) do update set name = excluded.name, website = excluded.website, sort = excluded.sort;
insert into public.brands (id, name, website, sort) values ('lavazza', 'Lavazza', 'https://www.lavazza.fr/fr/cafe/capsules-compatibles.html', 5)
  on conflict (id) do update set name = excluded.name, website = excluded.website, sort = excluded.sort;
insert into public.brands (id, name, website, sort) values ('cafe-royal', 'Café Royal', 'https://cafe-royal.com/fr-ch/produits/capsules-de-cafe', 6)
  on conflict (id) do update set name = excluded.name, website = excluded.website, sort = excluded.sort;

